use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn public_api_retries_transient_failures_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4, 10, 25), &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn public_api_returns_permanent_failure_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4, 10, 25), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn public_api_counts_first_call_and_caps_backoff() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5, 10, 25), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn public_api_calls_once_when_attempt_budget_is_zero() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(0, 10, 25), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert!(result.is_err());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

